        text: "Ako ay tulad ng maamong kordero na dinadala sa katayan. Hindi ko alam na may binabalak silang masama sa akin: “Sirain natin ang puno, pati ang bunga nito, At wakasan natin ang buhay niya, Para ang pangalan niya ay hindi na maalaala pa.”",
