        text: "Pero si Jehova ng mga hukbo ay humahatol nang makatarungan; Sinusuri niya ang kaloob-looban ng isip at ang puso. Ipakita mo sa akin ang paghihiganti mo sa kanila, Dahil sa iyo ko ipinagkatiwala ang kaso ko.",
