        text: "At sinabi ko: “O Kataas-taasang Panginoong Jehova! Sinasabi sa kanila ng mga propeta, ‘Hindi kayo makakakita ng espada, at hindi kayo daranas ng taggutom; sa halip ay bibigyan ko kayo ng tunay na kapayapaan sa lugar na ito.’”",
