        speaker: "Jeremias",
        text: "O Jehova, ang pag-asa ng Israel, Lahat ng umiiwan sa iyo ay mapapahiya. Ang mga nag-aapostata sa iyo ay mapapasulat sa alabok, Dahil iniwan nila si Jehova, ang bukal ng tubig na nagbibigay-buhay.",
