        text: "Pero kinalimutan ako ng bayan ko. Dahil naghahandog sila sa isang bagay na walang kabuluhan, At tinitisod nila ang iba mula sa landas na nilalakaran ng mga ito, ang mga sinaunang daan, Para lumakad sa mga daang makitid at hindi patag,",
