        text: "Ganoon din ang sinabi ko kay Haring Zedekias ng Juda: “Magpasailalim kayo sa pamatok ng hari ng Babilonya at maglingkod kayo sa kaniya at sa bayan niya, at patuloy kayong mabubuhay.",
