        text: "Pero kung sila ay mga propeta at kung ang salita ni Jehova ay nasa kanila, magmakaawa sana sila kay Jehova ng mga hukbo para hindi dalhin sa Babilonya ang natitirang mga kagamitan sa bahay ni Jehova, sa bahay ng hari ng Juda, at sa Jerusalem.’",
