        verse: 23,
        speaker: "Jehova",
        text: "Ito ang sinabi ni Jehova ng mga hukbo, ang Diyos ng Israel: “Muli nilang sasabihin ang mga salitang ito sa lupain ng Juda at sa mga lunsod nito kapag tinipon ko ang mga nabihag sa kanila: ‘Pagpalain ka nawa ni Jehova, O matuwid na tirahan, O banal na bundok.’",
