        verse: 12,
        speaker: "Jehova",
        text: "“Ito ang sinabi ni Jehova ng mga hukbo: ‘Sa tiwangwang na lugar na ito, na walang tao o alagang hayop, at sa lahat ng lunsod nito, ay muling magkakaroon ng mga pastulan na mapagpapahingahan ng kawan ng mga pastol.’",
