        verse: 20,
        speaker: "Jehova",
        text: "“Ito ang sinabi ni Jehova, ‘Kung masisira ninyo ang tipan ko sa araw at ang tipan ko sa gabi, para hadlangan ang pagdating ng araw at gabi sa takdang panahon nito,",
