        text: "Ang salitang dumating kay Jeremias mula kay Jehova, nang si Haring Nabucodonosor ng Babilonya at ang buong hukbo niya at ang lahat ng kaharian sa lupa na nasa ilalim ng pamumuno niya at ang lahat ng bayan ay nakikipaglaban sa Jerusalem at sa lahat ng lunsod nito:",
