        text: "“Ito ang sinabi ni Jehova na Diyos ng Israel, ‘Nakipagtipan ako sa mga ninuno ninyo noong araw na ilabas ko sila mula sa lupain ng Ehipto, kung saan sila inalipin, at sinabi ko:",
