        text: "“Sa mga araw na iyon at sa panahong iyon,” ang sabi ni Jehova, “ang bayan ng Israel at ang bayan ng Juda ay magsasama-sama. Maglalakad silang umiiyak, at sama-sama nilang hahanapin si Jehova na kanilang Diyos.",
