        verse: 18,
        speaker: "Jehova",
        text: "Kaya ito ang sinabi ni Jehova ng mga hukbo, ang Diyos ng Israel: ‘Paparusahan ko ang hari ng Babilonya at ang lupain niya gaya ng pagpaparusa ko sa hari ng Asirya.",
