        verse: 24,
        speaker: "Jehova",
        text: "Naglagay ako ng bitag para sa iyo, at nahuli ka, O Babilonya, At hindi mo alam iyon. Nahuli ka at nabihag, Dahil si Jehova ang kinalaban mo.",
