        text: "Pero ang Manunubos nila ay malakas. Jehova ng mga hukbo ang pangalan niya. Tiyak na ipaglalaban niya ang kaso nila, Para bigyan ng kapahingahan ang lupain At magpasapit ng kaguluhan sa mga taga-Babilonya.”",
