        text: "“Sa ligtas na mga pastulan ay may sasalakay na parang leon mula sa makakapal na palumpong sa kahabaan ng Jordan, pero bigla ko silang patatakasin mula sa lupain nila. At aatasan kong mamahala rito ang pinili ko. Dahil sino ang gaya ko, at sino ang hahamon sa akin? Sinong pastol ang makatatayo sa harap ko?",
